<script setup lang="ts">
import type { UnwrapNestedRefs } from 'vue'
import type { useKaban } from '~/composables/useKaban'
import type { KabanBlock, KabanFile } from '~~/shared/types/kaban'
import { kabanLink } from '~~/shared/utils/kaban'
import { createId } from '~/utils/browser'
import FileUpload from '../FileUpload.vue'
const props=defineProps<{controller:UnwrapNestedRefs<ReturnType<typeof useKaban>>;editing:boolean;active?:boolean;field:KabanBlock;index:number}>()
const field=toRef(props,'field')
const linkValue=computed(()=>field.value.type==='link'?field.value.value:'')
const safeLink=computed(()=>kabanLink(linkValue.value))
const c=props.controller,todoDrafts=reactive<Record<string,string>>({}),deletingFile=ref<KabanFile|null>(null)
const writable=computed(()=>!!c.draft?.canEdit&&!c.busy&&props.active!==false)
const blocks=computed(()=>c.draft?.blocks||[])
const icons={description:'i-lucide-align-left',link:'i-lucide-link',password:'i-lucide-key-round',todo:'i-lucide-list-checks',files:'i-lucide-paperclip'}
const fileBlockIds=computed(()=>new Set(blocks.value.filter(field=>field.type==='files').map(field=>field.id)))
const firstFiles=computed(()=>blocks.value.find(field=>field.type==='files')?.id)
function blockFiles(id:string){return c.files.filter(file=>file.blockId===id||id===firstFiles.value&&(!file.blockId||!fileBlockIds.value.has(file.blockId)))}
const orphanFiles=computed(()=>firstFiles.value?[]:c.files)
function canRemove(field:KabanBlock){return field.type!=='files'||(!c.filesLoading&&!blockFiles(field.id).length&&!c.pendingFiles.some(item=>item.blockId===field.id))}
function shift(index:number,delta:number){if(!writable.value||!c.draft?.blocks)return;const [field]=c.draft.blocks.splice(index,1);c.draft.blocks.splice(index+delta,0,field!)}
function remove(field:KabanBlock){if(writable.value&&canRemove(field)&&c.draft)c.draft.blocks=blocks.value.filter(item=>item.id!==field.id)}
function addTodo(field:KabanBlock,force=false){if((!writable.value&&!force)||!c.draft?.canEdit||c.busy||field.type!=='todo'||!todoDrafts[field.id]?.trim())return;const count=blocks.value.flatMap(item=>item.type==='todo'?item.items:[]).length;if(count>=100){c.formError='В задаче может быть до 100 пунктов списков дел.';return}field.items.push({id:createId(),text:todoDrafts[field.id]!.trim(),done:false});todoDrafts[field.id]=''}
function passwordValue(field:KabanBlock){return field.type==='password'&&field.entryId?field.vaultId+'/'+field.entryId:undefined}
function setPassword(field:KabanBlock,value:string|undefined){if(field.type!=='password'||!writable.value)return;const [vaultId,entryId]=(value||'').split('/');field.vaultId=vaultId||c.data?.board.vaultId||'personal';field.entryId=entryId||''}
const size=(value:number)=>value>=1048576?`${(value/1048576).toFixed(1)} МБ`:`${Math.ceil(value/1024)} КБ`
function pending(id:string){return c.pendingFiles.map((item,index)=>({...item,index})).filter(item=>item.blockId===id)}
watch(()=>props.active,active=>{if(!active)addTodo(props.field,true)})
defineExpose({flushTodos:()=>addTodo(props.field,true)})
</script>
<template>
<article class="kaban-field" :data-field-type="field.type">
   <header class="kaban-field-heading"><UIcon :name="icons[field.type]"/><UInput v-if="editing" v-model="field.title" :aria-label="`Название поля ${index+1}`" :maxlength="120" required :disabled="!writable" class="flex-1"/><h3 v-if="!editing">{{field.title}}</h3><template v-if="editing"><UButton type="button" size="xs" icon="i-lucide-arrow-up" color="neutral" variant="ghost" :aria-label="`Поднять поле ${field.title}`" :disabled="!writable||index===0" @click="shift(index,-1)"/><UButton type="button" size="xs" icon="i-lucide-arrow-down" color="neutral" variant="ghost" :aria-label="`Опустить поле ${field.title}`" :disabled="!writable||index===blocks.length-1" @click="shift(index,1)"/><UButton type="button" size="xs" icon="i-lucide-trash-2" color="error" variant="ghost" :aria-label="`Удалить поле ${field.title}`" :title="canRemove(field)?'Удалить поле':'Сначала удалите вложения из поля'" :disabled="!writable||!canRemove(field)" @click="remove(field)"/></template></header>
   <template v-if="field.type==='description'"><UTextarea v-if="editing" v-model="field.value" :aria-label="field.title" :rows="4" :maxlength="20000" placeholder="Добавьте описание…" :disabled="!writable" class="w-full"/><p v-if="!editing&&field.value" class="kaban-field-text">{{field.value}}</p><p v-if="!editing&&!field.value" class="kaban-help">Описание пока не добавлено.</p></template>
   <template v-if="field.type==='link'"><UInput v-if="editing" v-model="field.value" :aria-label="field.title" type="url" placeholder="https://…" :maxlength="2048" :disabled="!writable" class="w-full"/><a v-if="!editing&&safeLink" :href="safeLink" target="_blank" rel="noopener noreferrer" class="kaban-resource-link"><UIcon name="i-lucide-external-link"/><span>{{linkValue}}</span></a><p v-if="!editing&&!safeLink" class="kaban-help">Ссылка пока не добавлена.</p></template>
   <template v-if="field.type==='password'"><USelectMenu v-if="editing" :model-value="passwordValue(field)" :items="c.passwordOptions" value-key="value" :aria-label="field.title" placeholder="Выберите карточку пароля" :disabled="!writable" class="w-full" @update:model-value="value=>setPassword(field,value)"/><NuxtLink v-if="!editing&&c.passwordEntry(field.vaultId,field.entryId)" :to="{path:'/password',query:{vault:field.vaultId,entry:field.entryId}}" class="kaban-resource-link"><UIcon name="i-lucide-key-round"/><span>{{c.passwordEntry(field.vaultId,field.entryId)?.title}}</span><UIcon name="i-lucide-arrow-up-right"/></NuxtLink><p v-if="!editing&&!c.passwordEntry(field.vaultId,field.entryId)" class="kaban-help">{{field.entryId?'Карточка недоступна для вашего аккаунта или удалена.':'Карточка пароля пока не выбрана.'}}</p><p v-if="editing" class="kaban-help mt-2">Сохраняется только ссылка. Доступ к паролю определяется правами на карточку.</p></template>
   <template v-if="field.type==='todo'"><div class="kaban-section-title"><span>{{field.items.filter(item=>item.done).length}} / {{field.items.length}}</span></div><progress v-if="field.items.length" :value="field.items.filter(item=>item.done).length" :max="field.items.length" :aria-label="`Прогресс: ${field.title}`"/><div v-for="(item,itemIndex) in field.items" :key="item.id" class="kaban-todo-row"><UCheckbox v-model="item.done" :aria-label="`Выполнено: ${item.text}`" :disabled="!writable"/><UInput v-if="editing" v-model="item.text" :aria-label="`Пункт ${itemIndex+1} в ${field.title}`" :maxlength="500" required :disabled="!writable" class="flex-1"/><span v-if="!editing" class="kaban-todo-text" :class="{'todo-done':item.done}">{{item.text}}</span><UButton v-if="editing" type="button" icon="i-lucide-x" color="neutral" variant="ghost" :aria-label="`Удалить пункт ${itemIndex+1} в ${field.title}`" :disabled="!writable" @click="field.items.splice(itemIndex,1)"/></div><div v-if="editing" class="kaban-todo-row"><UInput v-model="todoDrafts[field.id]" :aria-label="`Новый пункт в ${field.title}`" placeholder="Добавить пункт…" :maxlength="500" :disabled="!writable" class="flex-1" @keydown.enter.prevent="addTodo(field)"/><UButton type="button" icon="i-lucide-plus" label="Добавить" size="sm" color="neutral" variant="outline" :disabled="!writable||!todoDrafts[field.id]?.trim()" @click="addTodo(field)"/></div><p v-if="!editing&&!field.items.length" class="kaban-help">Пунктов пока нет.</p></template>
   <template v-if="field.type==='files'"><FileUpload v-if="editing" :label="`Прикрепить: ${field.title}`" hint="До 20 файлов на задачу, каждый до 20 МБ. Загрузятся при сохранении." multiple :disabled="!writable||c.filesLoading" @change="event=>c.chooseFiles(event,field.id)"/><p v-if="c.filesLoading" class="kaban-help" role="status">Загружаем вложения…</p><div v-for="file in blockFiles(field.id)" :key="file.id" class="kaban-file"><UIcon :name="file.type.startsWith('image/')?'i-lucide-image':'i-lucide-file'"/><span><strong>{{file.name}}</strong><small>{{size(file.size)}}</small></span><UButton v-if="file.type.startsWith('image/')" type="button" icon="i-lucide-eye" color="neutral" variant="ghost" :aria-label="`Посмотреть ${file.name}`" @click="c.openFile(file,true)"/><UButton type="button" icon="i-lucide-download" color="neutral" variant="ghost" :aria-label="`Скачать ${file.name}`" @click="c.openFile(file)"/><UButton v-if="editing" type="button" icon="i-lucide-trash-2" color="error" variant="ghost" :disabled="!writable" :aria-label="`Удалить ${file.name}`" @click="deletingFile=file"/></div><div v-for="item in pending(field.id)" :key="item.index" class="kaban-file"><UIcon name="i-lucide-paperclip"/><span><strong>{{item.file.name}}</strong><small>{{size(item.file.size)}} · Будет загружен</small></span><UButton type="button" icon="i-lucide-x" color="neutral" variant="ghost" :aria-label="`Убрать ${item.file.name}`" :disabled="!writable" @click="c.pendingFiles=c.pendingFiles.filter((_,i)=>i!==item.index)"/></div><p v-if="!editing&&!c.filesLoading&&!blockFiles(field.id).length" class="kaban-help">Вложений пока нет.</p></template>
  </article>
 <UModal :open="!!deletingFile" title="Удалить вложение?" :description="deletingFile?.name" :dismissible="!c.busy" @update:open="value=>{if(!value)deletingFile=null}"><template #body><UAlert v-if="c.formError" color="error" :description="c.formError"/></template><template #footer><UButton label="Отмена" color="neutral" variant="outline" :disabled="c.busy" @click="deletingFile=null"/><UButton label="Удалить файл" color="error" :loading="c.busy" @click="async()=>{if(deletingFile){await c.removeFile(deletingFile);deletingFile=null}}"/></template></UModal>
</template>
